/bin/bash -lc "cat > /tmp/folio-invoice-verify.cjs <<'EOF'
const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const html=fs.readFileSync(process.argv[2],'utf8');
const script=html.split('<script>')[1].split('</script>')[0];
class Element {
 constructor(dataset={}){this.dataset=dataset;this.textContent='';this.innerHTML='';this.value='';this.hidden=false;this.style={};this.handlers={};this.attributes={};this.classes=new Set();this.classList={add:x=>this.classes.add(x),remove:x=>this.classes.delete(x),toggle:(x,b)=>b?this.classes.add(x):this.classes.delete(x)};}
 addEventListener(event,fn){this.handlers[event]=fn;}
 setAttribute(k,v){this.attributes[k]=v;}
 removeAttribute(k){delete this.attributes[k];}
 setCustomValidity(s){this.validity=s;}
 showModal(){this.open=true;}
 close(){this.open=false;}
 scrollIntoView(){}
 reset(){}
 click(){this.handlers.click?.({target:this});}
}
const elements={}; for(const m of html.matchAll(/id=\"(["'^"]+)"/g))elements['"'#'+m[1]]=new Element();
const views=['overview','all','overdue','draft'].map(view=>new Element({view}));
const filters=['all','pending','paid','overdue','draft'].map(filter=>new Element({filter}));
const closed=[new Element({close:'create-dialog'}),new Element({close:'detail-dialog'})];
const local=new Map();
const context={console,structuredClone,Intl,Date,FormData:class{constructor(form){this.data=form.data}get(k){return this.data[k]}},setTimeout:()=>1,clearTimeout:()=>{},localStorage:{getItem:k=>local.get(k)??null,setItem:(k,v)=>local.set(k,v)},document:{querySelector:s=>elements[s],querySelectorAll:s=>s==='[data-view]'?views:s==='[data-filter]'||s==='.tab'?filters:s==='[data-close]'?closed:s==='dialog'?[elements['#create-dialog'],elements['#detail-dialog']]:[],createElement:()=>new Element()},Blob,URL};
vm.createContext(context);vm.runInContext(script,context);
const run=s=>vm.runInContext(s,context);
assert.equal(elements['#nav-total'].textContent,10);
assert.equal(elements['#nav-overdue'].textContent,2);
assert.match(elements['#outstanding-value'].innerHTML,/13,950/);
assert.match(elements['#paid-value'].innerHTML,/8,800/);
assert.equal((elements['#invoice-rows'].innerHTML.match(/<tr>/g)||[]).length,6);
run(\"setFilter('overdue')\");assert.equal(elements['#results-count'].textContent,'Showing 1–2 of 2 invoices');
assert.match(elements['#invoice-rows'].innerHTML,/4 days overdue/);assert.match(elements['#invoice-rows'].innerHTML,/7 days overdue/);
run(\"setFilter('all'); search='juniper'; render()\");assert.equal(elements['#results-count'].textContent,'Showing 1–1 of 1 invoice');
run(\"search='no-such-client'; render()\");assert.equal(elements['#empty'].hidden,false);
run(\"search=''; page=2; render()\");assert.match(elements['#results-count'].textContent,/7–10/);
const form={data:{client:'Willow <Co>',amount:'3250.50',due:'2026-11-08',status:'pending',description:'Design sprint'}};
elements['#invoice-form'].handlers.submit({preventDefault(){},target:form});
assert.equal(elements['#nav-total'].textContent,11);assert.match(elements['#outstanding-value'].innerHTML,/17,200/);assert.match(elements['#invoice-rows'].innerHTML,/Willow &lt;Co&gt;/);
assert.equal(JSON.parse(local.get('folio-invoices-v1')).length,11);
run('showDetail(41)');assert.equal(elements['#detail-title'].textContent,'Forma Studio');assert.equal(elements['#detail-dialog'].open,true);
elements['#mark-paid'].click();assert.equal(elements['#nav-overdue'].textContent,1);assert.match(elements['#overdue-value'].innerHTML,/1,600/);assert.match(elements['#paid-value'].innerHTML,/10,650/);
run('showDetail(35)');elements['#mark-paid'].click();assert.equal(elements['#nav-draft'].textContent,0);assert.match(elements['#outstanding-value'].innerHTML,/16,600/);
run(\"setView('overdue')\");assert.equal(elements['#page-title'].textContent,'Overdue invoices');assert.equal(elements['#results-count'].textContent,'Showing 1–1 of 1 invoice');
console.log('PASS: initial totals, overdue dates, search, empty state, pagination, invoice creation, escaping, persistence, payment updates, draft transitions, and navigation.');
EOF
